import { sql } from 'drizzle-orm'
import { check, integer, sqliteTable, text } from 'drizzle-orm/sqlite-core'
import { user } from './auth-schema.ts'

// Better Auth's tables, generated by `bun run db:auth-schema`. A member's display name is `user.name`.
export * from './auth-schema.ts'

export const BOOKING_STATUSES = ['CONFIRMED', 'PENDING'] as const

export const bookings = sqliteTable(
  'bookings',
  {
    id: integer('id').primaryKey({ autoIncrement: true }),
    // `title` and the dates are nullable as they are in Supabase, so the import (#18) is lossless.
    title: text('title'),
    // Civil dates (`YYYY-MM-DD`), never instants: see "Calendar day" in CONTEXT.md.
    startDate: text('start_date'),
    endDate: text('end_date'),
    status: text('status', { enum: BOOKING_STATUSES }).notNull().default('CONFIRMED'),
    createdAt: text('created_at')
      .notNull()
      .default(sql`(strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))`),
    booker: text('booker').references(() => user.id, { onDelete: 'set null' }),
  },
  (t) => [
    check('bookings_status_check', sql`${t.status} in (${sql.raw(BOOKING_STATUSES.map((s) => `'${s}'`).join(', '))})`),
  ],
)
